FM pFM = FM ();
pu = [ n ];
pFM - > ranGen ( seed , n , pu );
Rprintf ( " Your random numbers are \ n " );
( i = 0; i < n ; i ++)
Rprintf ( " % f \ n " , pu [ i ]);
pFM ;
[] pu ;
